window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[227]={"id":"227","numero":227,"titre":"Insuffisance veineuse chronique. Varices","objectifs":[{"id":"227-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","contenu":"<p>L'<span class=\"kw-def\">insuffisance veineuse chronique (IVC)</span> est une <strong>dysfonction du système veineux profond et/ou superficiel</strong>. Elle résulte d'une <span class=\"kw-def\">incontinence valvulaire</span>, avec ou sans oblitération veineuse associée, et touche préférentiellement les <strong>membres inférieurs</strong>.</p>\n      <p>Les <span class=\"kw-def\">varices</span> sont une <strong>dilatation permanente et pathologique</strong> d'une ou plusieurs <span class=\"kw-clinique\">veines superficielles</span> des membres inférieurs. Ce sont des veines dilatées et tortueuses (en orthostatisme, <span class=\"kw-clinique\">diamètre</span> <span class=\"kw-chiffre\">&gt; 3 mm</span>), sous-cutanées et visibles à l'inspection ; elles sont associées à un <span class=\"kw-def\">reflux</span> entraînant une stase du sang veineux.</p>\n      <div class=\"callout callout-warn\">⚠️ Piège : les varices pathologiques sont à distinguer des « varices du sportif », liées à une simple <span class=\"kw-clinique\">lyse du tissu adipeux</span> et sans valeur pathologique.</div>\n      <p><strong>Rappel anatomique</strong> — le retour veineux du membre inférieur repose sur trois réseaux :</p>\n      <table >\n        <thead>\n          <tr><th>Réseau</th><th>Part du retour veineux</th><th>Constitution</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Réseau profond</strong></td><td><span class=\"kw-chiffre\">90 %</span></td><td><strong>Proximal</strong> (sus-poplité) : veines poplitée, fémorale, iliaque, cave<br><strong>Distal</strong> (sous-poplité) : veines jambières et surales</td></tr>\n          <tr><td><strong>Réseau superficiel</strong><br><em>(impliqué dans les varices)</em></td><td><span class=\"kw-chiffre\">10 %</span></td><td>Grande veine saphène (saphène interne) ; petite veine saphène (saphène externe) ; reliées entre elles par des <span class=\"kw-clinique\">veines communicantes</span></td></tr>\n          <tr><td><strong>Veines perforantes</strong></td><td>—</td><td>Relient le réseau superficiel au réseau profond</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/anatomie-reseau-veineux-mi.png\" alt=\"Schéma anatomique du réseau veineux du membre inférieur : veine iliaque, fémorale, grande et petite veines saphènes, veines perforantes\" loading=\"lazy\">\n        <figcaption>Réseau veineux du membre inférieur : réseau profond (poplitée, fémorale, iliaque), réseau superficiel (grande et petite veines saphènes) et veines perforantes les reliant. Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <p><strong>📌 Classification <span class=\"kw-def\">CEAP</span> (LiSA)</strong> — outil de référence pour parler le même langage devant une IVC. Combine 4 axes :</p>\n      <table >\n        <thead><tr><th>Axe</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>C — Clinique</strong> (grade 0-6, suffixe <em>a</em>=asymptomatique / <em>s</em>=symptomatique)</td><td>0 : aucun signe visible ou palpable · 1 : <span class=\"kw-clinique\">télangiectasies / veines réticulaires</span> · 2 : <span class=\"kw-clinique\">varices</span> · 3 : <span class=\"kw-clinique\">œdème</span> · 4 : troubles trophiques (dermite ocre, atrophie blanche, lipodermatosclérose) · 5 : ulcère cicatrisé · 6 : <span class=\"kw-alerte\">ulcère actif</span></td></tr>\n          <tr><td><strong>E — Étiologie</strong></td><td>Ec : congénitale · <strong>Ep : primitive</strong> (maladie variqueuse) · <strong>Es : secondaire</strong> (syndrome post-thrombotique)</td></tr>\n          <tr><td><strong>A — Anatomie</strong></td><td>As : superficiel · <strong>Ad : profond</strong> (deep) · Ap : perforantes</td></tr>\n          <tr><td><strong>P — Physiopathologie</strong></td><td><strong>Pr : reflux</strong> · <strong>Po : obstruction</strong> · Pr,o : les deux</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">La CEAP <strong>n'est pas à apprendre par cœur</strong> mais LiSA en attend la compréhension : elle structure toute la démarche clinique de l'IVC (grade C dicte l'urgence de la prise en charge, E/P orientent l'étiologie et le mécanisme).</div>","frequence":0},{"id":"227-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux mécanismes physiopathologiques responsables de l’IVC","contenu":"<p>Le <span class=\"kw-def\">retour veineux</span> s'effectue contre la <span class=\"kw-def\">pression orthostatique</span> (<span class=\"kw-clinique\">pesanteur</span>), grâce à la synergie de plusieurs acteurs :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Valvules veineuses</span></strong> : <span class=\"kw-def\">centripètes et unidirectionnelles</span>, présentes dans toutes les veines du membre inférieur — ce sont les dispositifs <span class=\"kw-clinique\">anti-reflux</span>.</li>\n        <li><strong>Pompe musculaire du mollet</strong> (acteur majeur) : à la <strong>contraction</strong>, le muscle comprime le réseau profond contenu dans une <span class=\"kw-def\">aponévrose inextensible</span> et propulse le flux vers le haut ; au <strong>relâchement</strong>, le sang du réseau superficiel est aspiré vers le réseau profond.</li>\n        <li><strong><span class=\"kw-def\">Pression dynamique résiduelle</span></strong> : issue de l'éjection du ventricule gauche transmise jusqu'au versant veineux.</li>\n        <li><strong>Systèmes accessoires</strong> : <span class=\"kw-def\">semelle plantaire de Lejars</span> (statique plantaire) et <span class=\"kw-def\">système abdomino-diaphragmatique</span> (le retour veineux se fait pendant l'<span class=\"kw-clinique\">expiration</span>, quand la veine cave inférieure n'est pas comprimée par le diaphragme).</li>\n      </ul>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/pompe-musculo-aponevrotique-mollet.png\" alt=\"Schéma de la pompe musculaire du mollet : au relâchement aspiration du sang, à la contraction compression du réseau veineux profond\" loading=\"lazy\">\n        <figcaption>Pompe musculaire du mollet : la contraction comprime le réseau veineux profond et propulse le sang vers le cœur ; le relâchement aspire le sang du réseau superficiel. Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <p>Tout dysfonctionnement de cette coopération crée une <strong>anomalie du retour veineux</strong>. Deux mécanismes principaux sont responsables de l'IVC :</p>\n      <ul>\n        <li><span class=\"kw-def\">Reflux valvulaire</span> : incontinence des valvules anti-reflux.</li>\n        <li><span class=\"kw-def\">Obstruction veineuse</span> : obstacle sur le trajet du retour veineux.</li>\n      </ul>\n      <p>Ces deux mécanismes aboutissent à une <span class=\"kw-alerte\">hypertension veineuse</span>, qui conduit à une <span class=\"kw-alerte\">souffrance microcirculatoire et tissulaire</span> — origine des <span class=\"kw-clinique\">troubles trophiques</span> et de l'<span class=\"kw-clinique\">ulcère veineux</span>.</p>","frequence":0},{"id":"227-3","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un syndrome post-thrombotique","contenu":"<p>Le <span class=\"kw-def\">syndrome post-thrombotique (SPT)</span> est une <strong>séquelle de thrombose veineuse</strong>, survenant généralement quelques années après une <span class=\"kw-etio\">TVP</span>. Environ <span class=\"kw-chiffre\">20 à 50 %</span> des patients ayant fait une phlébite développent une IVC dans les <span class=\"kw-chiffre\">5 à 10 ans</span> ; environ <span class=\"kw-chiffre\">5 à 10 %</span> développent un SPT sévère. Le risque est particulièrement important après une <span class=\"kw-alerte\">thrombose ilio-fémorale</span>.</p>\n      <div class=\"callout callout-info\">⚠️ Le SPT concerne le <strong>réseau veineux profond</strong> — à ne pas confondre avec les varices, qui sont superficielles.</div>\n      <p><strong><span class=\"kw-def\">Physiopathologie</span></strong> — deux mécanismes possibles :</p>\n      <ul>\n        <li><span class=\"kw-def\">Obstruction résiduelle chronique</span> d'une veine profonde : élévation des pressions en amont du <span class=\"kw-etio\">thrombus</span>, puis redistribution du retour veineux vers le réseau superficiel → varices.</li>\n        <li><span class=\"kw-def\">Syndrome de recanalisation</span> du <span class=\"kw-etio\">thrombus</span> : la réaction <span class=\"kw-etio\">inflammatoire</span> locale détruit les valvules au niveau du thrombus → <span class=\"kw-alerte\">reflux valvulaire profond</span>.</li>\n      </ul>\n      <p><strong><span class=\"kw-def\">Diagnostic positif</span></strong> : présentation clinique associant des signes d'IVC et des signes d'antécédent de phlébite ; <span class=\"kw-imagerie\">échodoppler veineux</span> montrant les séquelles de <span class=\"kw-etio\">TVP</span> (syndrome obstructif et reflux profonds) ; le <span class=\"kw-def\">score de Villalta</span> en cote la sévérité.</p>\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Score</span> de Villalta</th><th>Items évalués</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Symptômes subjectifs</strong> (patient)</td><td><span class=\"kw-clinique\">Lourdeur</span> ; <span class=\"kw-clinique\">douleur</span> ; <span class=\"kw-clinique\">crampes</span> ; <span class=\"kw-clinique\">prurit</span> ; <span class=\"kw-clinique\">paresthésies</span></td></tr>\n          <tr><td><strong>Signes objectifs</strong> (médecin)</td><td><span class=\"kw-clinique\">Œdème</span> ; douleur à la pression des mollets ; <span class=\"kw-clinique\">induration de la peau</span> ; <span class=\"kw-clinique\">hyperpigmentation</span> ; <span class=\"kw-clinique\">rougeur</span></td></tr>\n          <tr><td><strong>Cotation</strong></td><td>0 = absent, 1 = léger, 2 = modéré, 3 = sévère ; ulcère présent = 1, absent = 0</td></tr>\n          <tr><td><strong>Interprétation</strong></td><td><span class=\"kw-chiffre\">≤ 4</span> : absence de SPT<br><span class=\"kw-chiffre\">5 à 14</span> : SPT modéré<br><span class=\"kw-chiffre\">≥ 15</span> ou ulcère présent : SPT sévère</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Prévention</strong> : dès le diagnostic de phlébite, <span class=\"kw-ttt\">anticoagulation efficace</span> + <span class=\"kw-ttt\">compression élastique</span>. La compression instaurée dès la phase initiale de la <span class=\"kw-etio\">TVP</span> pendant <span class=\"kw-chiffre\">≥ 3 mois</span> réduit le risque de SPT de <span class=\"kw-chiffre\">50 %</span>.</p>\n      <div class=\"callout callout-danger\">⚠️ L'<span class=\"kw-ci\">éveinage est contre-indiqué</span> en cas d'insuffisance veineuse sur SPT : les varices secondaires suppléent l'obstruction veineuse profonde.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":2},{"id":"227-4","rang":"B","rubrique":"Étiologies","titre":"Connaître les étiologies des varices et de l’IVC","contenu":"<p>Les étiologies des varices et de l'IVC se répartissent en trois grandes familles :</p>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Insuffisance veineuse primitive</strong><br><em>(la plus fréquente)</em></td><td><span class=\"kw-etio\">Maladie variqueuse</span> (varices essentielles), touchant les veines <strong>superficielles</strong> : varices systématisées (aux dépens de la grande ou petite veine saphène) ou non systématisées (« non-saphènes », perforantes ou pelviennes).<br>Plus rarement : <span class=\"kw-etio\">insuffisance valvulaire primitive profonde</span> (rare, voire exceptionnelle) → reflux veineux profond — sujet jeune : agénésie/dysgénésie valvulaire ; sujet âgé : dégénérescence.</td></tr>\n          <tr><td><strong>Insuffisance veineuse secondaire</strong></td><td><span class=\"kw-etio\">Syndrome post-thrombotique</span> : survient <span class=\"kw-chiffre\">5 à 10 ans</span> après une phlébite dans <span class=\"kw-chiffre\">20 à 50 %</span> des cas.<br><span class=\"kw-etio\">Syndromes veineux compressifs</span> : tumeurs pelviennes (thromboses ilio-fémorales) ; <span class=\"kw-def\">syndrome de Cockett</span> — l'artère iliaque commune droite comprime la veine iliaque commune gauche.</td></tr>\n          <tr><td><strong>Insuffisance veineuse fonctionnelle</strong></td><td>Retour veineux défaillant mais veines <strong>morphologiquement normales</strong> ; fréquente chez le sujet âgé : <span class=\"kw-etio\">réduction de la marche</span> ; <span class=\"kw-etio\">altération de la dynamique cardio-respiratoire</span> (ex. <span class=\"kw-def\">insuffisance cardiaque</span>) ; <span class=\"kw-etio\">ankylose tibio-tarsienne</span> ; <span class=\"kw-etio\">perte de volume musculaire</span>.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 226 — <span class=\"kw-def\">Thrombose veineuse profonde</span> - EP</em></p>","frequence":0},{"id":"227-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les facteurs favorisant l’IVC","contenu":"<p>L'IVC et les varices partagent les mêmes <span class=\"kw-etio\">facteurs de risque</span> :</p>\n      <ul>\n        <li><span class=\"kw-etio\">Hérédité</span> — facteur majeur.</li>\n        <li><span class=\"kw-etio\">Âge</span> et <span class=\"kw-etio\">sexe féminin</span>.</li>\n        <li><span class=\"kw-etio\">Grossesses multiples</span>.</li>\n        <li><span class=\"kw-etio\">Sédentarité</span>, <span class=\"kw-etio\">obésité</span> et <span class=\"kw-etio\">surpoids</span>.</li>\n        <li><span class=\"kw-etio\">Constipation chronique</span>.</li>\n        <li>Exposition à la <span class=\"kw-etio\">chaleur</span>.</li>\n        <li><span class=\"kw-etio\">Orthostatisme prolongé</span> (station debout immobile).</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Piège classique : la <strong>marche prolongée n'est PAS un <span class=\"kw-def\">facteur de risque</span></strong> d'IVC — c'est l'orthostatisme prolongé (station debout immobile) qui l'est. La marche active au contraire la pompe musculaire du mollet.</div>","frequence":0},{"id":"227-6","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence de l’IVC","contenu":"<p>L'IVC est un véritable <strong><span class=\"kw-def\">problème de santé publique</span></strong> :</p>\n      <ul>\n        <li><span class=\"kw-def\">Prévalence</span> globale d'environ <span class=\"kw-chiffre\">30 à 60 %</span> dans les pays industrialisés.</li>\n        <li>Environ <span class=\"kw-chiffre\">20 millions</span> d'IVC et plus de <span class=\"kw-chiffre\">400 000</span> ulcères d'origine veineuse.</li>\n        <li>Nette <strong>prédominance féminine</strong> (<span class=\"kw-chiffre\">3 femmes pour 1 homme</span>), qui tend à s'équilibrer avec l'âge.</li>\n      </ul>","frequence":0},{"id":"227-7","rang":"A","rubrique":"Diagnostic positif","titre":"Identifier les varices et l’IVC","contenu":"<p><strong>Symptômes</strong> — fréquents, variés et peu spécifiques, leur intensité varie avec la stase veineuse :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Lourdeurs</span> et <span class=\"kw-clinique\">pesanteurs</span> des membres inférieurs, <span class=\"kw-clinique\">crampes</span>, fatigabilité du mollet.</li>\n        <li><span class=\"kw-clinique\">Phlébalgie</span> : trajet veineux douloureux, <strong>sans induration</strong> (à la différence de la thrombose veineuse superficielle).</li>\n        <li><span class=\"kw-clinique\">Prurit</span> et gêne esthétique.</li>\n      </ul>\n      <p><strong>Symptômes moins connus</strong> :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Impatiences nocturnes</span> : peuvent s'intégrer dans le syndrome des jambes sans repos.</li>\n        <li>Brûlures, rougeur du pied après quelques heures de sommeil ou en déclivité, soulagées par le froid.</li>\n        <li><span class=\"kw-clinique\">Claudication intermittente veineuse</span> : n'empêche pas la poursuite de la marche, ne cède pas à l'arrêt de la marche mais cède en <strong>décubitus</strong> — c'est l'inverse de la <span class=\"kw-clinique\">claudication</span> artérielle.</li>\n      </ul>\n      <table >\n        <thead>\n          <tr><th>Facteurs d'aggravation</th><th>Facteurs d'amélioration</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>Station debout ou assise prolongée ; chaleur ; <span class=\"kw-ci\">grossesse</span> ; œstroprogestatifs ; période prémenstruelle</td><td>Froid ; surélévation des membres inférieurs ; décubitus ; exercice physique ; compression veineuse élastique</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Signes cutanés</strong> — du plus précoce au plus avancé :</p>\n      <table >\n        <thead>\n          <tr><th>Signe</th><th>Description</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Télangiectasies</span></td><td>Dilatations intradermiques de petit calibre (<span class=\"kw-chiffre\">1 mm</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Veines réticulaires</span></td><td>Dilatations sous-dermiques ramifiées (<span class=\"kw-chiffre\">1 à 3 mm</span>) ; au niveau de la cheville ou de l'arche plantaire, elles forment la <span class=\"kw-clinique\">corona phlebectatica</span> (couronne phlébectasique), <strong>signe précurseur d'<span class=\"kw-clinique\">ulcère veineux</span></strong></td></tr>\n          <tr><td><span class=\"kw-clinique\">Varices</span></td><td>Veines variqueuses sous-cutanées (<span class=\"kw-chiffre\">&gt; 3 mm</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Œdème</span></td><td>Blanc, mou, prend le godet, avec nette <strong>recrudescence vespérale</strong></td></tr>\n          <tr><td>Troubles trophiques</td><td><span class=\"kw-clinique\">Eczéma variqueux</span> ; <span class=\"kw-clinique\">dermite ocre</span> ; <span class=\"kw-clinique\">atrophie blanche de Milian</span> (petites zones blanc porcelaine malléolaires, ischémie cutanée annonçant l'ulcère) ; <span class=\"kw-clinique\">hypodermite / lipodermatosclérose</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Ulcère veineux</span></td><td><span class=\"kw-def\">Stade</span> ultime de l'IVC</td></tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/varices-saphene-interne.png\" alt=\"Photographie clinique de varices : veines variqueuses dilatées et tortueuses sur la jambe\" loading=\"lazy\">\n        <figcaption>Varices : veines superficielles dilatées, tortueuses et saillantes sur le membre inférieur. Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/227/veines-reticulaires.png\" alt=\"Photographie clinique de veines réticulaires : dilatations veineuses sous-dermiques ramifiées de petit calibre\" loading=\"lazy\">\n        <figcaption>Veines réticulaires : dilatations veineuses sous-dermiques ramifiées de petit calibre (<span class=\"kw-chiffre\">1 à 3 mm</span>). Source : fiche source EDN item 227.</figcaption>\n      </figure>\n      <p><strong>Examen clinique</strong> : bilatéral et comparatif, patient en escabeau de phlébologie. Il associe l'<strong>inspection</strong> (varices, varicosités, complications cutanées), la <strong>palpation</strong> (phlébalgie, recherche d'induration évoquant une thrombose) et l'<strong>auscultation</strong> (un souffle évoque une <span class=\"kw-clinique\">fistule</span> artério-veineuse). Les manœuvres cliniques (signe du flot, signe de Schwartz, épreuve de Trendelenburg) sont <strong>hors programme</strong>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 350 — Grosse jambe rouge aiguë</em></p>","frequence":2},{"id":"227-8","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître un ulcère variqueux","contenu":"<p>L'<span class=\"kw-def\">ulcère veineux</span> (ou ulcère variqueux) est le plus fréquent des ulcères de jambe — il en représente <span class=\"kw-chiffre\">80 %</span>. La distinction avec l'<span class=\"kw-def\">ulcère artériel</span> est un point clé du raisonnement diagnostique :</p>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th><span class=\"kw-clinique\">Ulcère veineux</span></th><th><span class=\"kw-clinique\">Ulcère artériel</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Femme <span class=\"kw-chiffre\">&gt; 50 ans</span> (≈ <span class=\"kw-chiffre\">1,5 F / 1 H</span>) ; ATCD de <span class=\"kw-etio\">TVP</span>, varices, <span class=\"kw-etio\">surpoids</span></td><td>Homme <span class=\"kw-chiffre\">&gt; 50 ans</span> ; <span class=\"kw-etio\">FDR cardiovasculaires</span> ; ATCD de <span class=\"kw-clinique\">claudication</span> intermittente</td></tr>\n          <tr><td>Localisation</td><td><strong>Péri-malléolaire</strong>, jusqu'au 1/3 inférieur du mollet ; <strong>bord régulier</strong></td><td>Zones d'appui et de frottement (pied : orteils, dos et bord externe, talon) ; parfois face antérieure (ulcère « suspendu »)</td></tr>\n          <tr><td>Taille</td><td>Souvent étendu, parfois circonférentiel</td><td>Petite taille</td></tr>\n          <tr><td>Douleur</td><td>Peu ou pas douloureux</td><td><span class=\"kw-alerte\">Douloureux</span>, habituellement intense</td></tr>\n          <tr><td>Profondeur</td><td>Superficiel, non creusant</td><td><span class=\"kw-alerte\">Creusant</span>, risque d'exposition articulaire / tendineuse / osseuse</td></tr>\n          <tr><td>Fond</td><td>Exsudatif, fibrineux</td><td>Atone, pâle</td></tr>\n          <tr><td>Peau péri-ulcéreuse</td><td>Varices, télangiectasies, <span class=\"kw-clinique\">eczéma variqueux</span>, <span class=\"kw-clinique\">dermite ocre</span>, atrophie blanche, <span class=\"kw-clinique\">corona phlebectatica</span> ; examen artériel normal</td><td>Peau luisante, dépilée ; baisse de la température cutanée ; <span class=\"kw-alerte\">abolition des pouls périphériques</span></td></tr>\n          <tr><td><span class=\"kw-bio\">IPS</span></td><td>Normal : <span class=\"kw-chiffre\">0,9 à 1,3</span> (<span class=\"kw-clinique\">ulcère veineux</span> pur)</td><td><span class=\"kw-chiffre\">&lt; 0,9</span> ; entre <span class=\"kw-chiffre\">0,7 et 0,9</span> = ulcère mixte à prédominance veineuse ; <span class=\"kw-chiffre\">&gt; 1,3</span> = artères calcifiées</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\">⚠️ Devant tout ulcère de jambe, la mesure de l'<span class=\"kw-bio\">IPS</span> est systématique : elle conditionne la possibilité d'une compression élastique (<span class=\"kw-ci\">contre-indiquée</span> si artériopathie sévère).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 228 — Ulcère de la jambe · 225 — Artériopathie oblitérante - anévrysme</em></p>","frequence":1},{"id":"227-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les méthodes diagnostiques de l’IVC","contenu":"<p>L'<span class=\"kw-imagerie\">échographie-Doppler veineuse des membres inférieurs</span>, réalisée en <strong><span class=\"kw-imagerie\">position debout</span></strong>, est l'<strong><span class=\"kw-def\">examen de référence</span></strong> du diagnostic d'IVC.</p>\n      <p><strong>Indications</strong> :</p>\n      <ul>\n        <li>Confirmer le diagnostic d'IVC.</li>\n        <li>Bilan <strong>pré-opératoire</strong> (systématique avant <span class=\"kw-ttt\">chirurgie variqueuse</span>).</li>\n        <li>Bilan <strong>pré-sclérose</strong> : <span class=\"kw-imagerie\">cartographie veineuse</span> et mesure du <span class=\"kw-clinique\">diamètre</span> des varices.</li>\n        <li>Bilan d'un <span class=\"kw-clinique\">ulcère</span> des membres inférieurs.</li>\n        <li>Suspicion de <span class=\"kw-etio\">TVP</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\">Les manœuvres cliniques (signe du flot, signe de Schwartz, épreuve de Trendelenburg) sont <strong>hors programme</strong> de l'EDN.</div>","frequence":0},{"id":"227-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de prise en charge thérapeutiques de l’IVC","contenu":"<p><strong>1. Mesures générales et hygiène de vie</strong> — socle du traitement :</p>\n      <ul>\n        <li>Surélévation des jambes et des pieds de <span class=\"kw-chiffre\">7 à 10 cm</span> au-dessus du lit.</li>\n        <li>Lutte contre le <span class=\"kw-etio\">surpoids</span> et la <span class=\"kw-etio\">sédentarité</span> (<span class=\"kw-ttt\">marche régulière quotidienne</span>).</li>\n        <li>Éviter de croiser les jambes en position assise et les stations debout immobiles prolongées.</li>\n        <li>Éviter le chauffage par le sol, les bains chauds et l'exposition prolongée au soleil.</li>\n        <li>Prise en charge de la <span class=\"kw-clinique\">constipation</span>.</li>\n      </ul>\n      <p><strong>2. Compression élastique</strong> — action hémodynamique et microcirculatoire, avec une pression dégressive de la cheville vers la cuisse. Pose le <strong>matin</strong>, dans l'heure suivant le lever. Quatre classes selon la pression exercée à la cheville :</p>\n      <table >\n        <thead>\n          <tr><th>Classe</th><th>Pression</th><th>Indications principales</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">Classe 1</span></td><td><span class=\"kw-chiffre\">10 à 15 mmHg</span></td><td>Prévention de la <span class=\"kw-etio\">TVP</span> ; IVC fonctionnelle</td></tr>\n          <tr><td><span class=\"kw-chiffre\">Classe 2</span></td><td><span class=\"kw-chiffre\">15,1 à 20 mmHg</span></td><td>Varices ; <span class=\"kw-etio\">TVP</span> ; post-opératoire de <span class=\"kw-ttt\">chirurgie variqueuse</span></td></tr>\n          <tr><td><span class=\"kw-chiffre\">Classe 3</span></td><td><span class=\"kw-chiffre\">20,1 à 36 mmHg</span></td><td>SPT ; <span class=\"kw-clinique\">œdème</span> veineux chronique ; <span class=\"kw-clinique\">troubles trophiques</span> ; ulcère cicatrisé</td></tr>\n          <tr><td><span class=\"kw-chiffre\">Classe 4</span></td><td><span class=\"kw-chiffre\">&gt; 36 mmHg</span></td><td>Insuffisance lymphatique ; <span class=\"kw-clinique\">ulcère veineux</span> cicatrisé ou ouvert</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\">⚠️ <strong><span class=\"kw-ci\">Contre-indications</span> de la compression élastique</strong> : <span class=\"kw-ci\">artériopathie oblitérante avec IPS &lt; 0,6</span> ; <span class=\"kw-ci\">thrombose veineuse septique</span> ; <span class=\"kw-ci\">phlegmatia caerulea</span> (phlébite bleue) ; <span class=\"kw-ci\">microangiopathie diabétique avec TcPO2 &lt; 30 mmHg</span>.</div>\n      <p><strong>3. Traitement <span class=\"kw-etio\">médicamenteux</span></strong> : les <span class=\"kw-ttt\">veinotropes</span> (veinotoniques, veino-actifs) ont un <strong>effet faible</strong>. Ils ne sont indiqués qu'en cas de gêne fonctionnelle, <strong>à titre adjuvant</strong> de l'hygiène de vie et de la compression, en cures séquentielles courtes.</p>\n      <p><strong>4. Destruction des veines pathologiques</strong> — indiquée en cas de <span class=\"kw-clinique\">varices</span> :</p>\n      <ul>\n        <li><strong>Traitements endovasculaires</strong> : <span class=\"kw-ttt\">sclérothérapie</span> (injection d'un produit sclérosant) ; <span class=\"kw-ttt\">techniques thermiques endoveineuses</span> (<span class=\"kw-ttt\">laser</span>, radiofréquence) — <strong>traitement de 1ʳᵉ intention</strong> en l'absence d'indication de sclérothérapie.</li>\n        <li><strong>Traitement chirurgical</strong> (indications de plus en plus réduites) : <span class=\"kw-ttt\">éveinage par stripping</span> ; <span class=\"kw-ttt\">phlébectomies</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\">⚠️ Piège : les <strong>varices secondaires à un SPT doivent habituellement être respectées</strong> — elles suppléent l'obstruction veineuse profonde. De même, chez un patient avec FDR cardiovasculaires ou maladie athéromateuse, rester conservateur sur les troncs saphènes (réserve possible pour un <span class=\"kw-ttt\">pontage</span> artériel ultérieur).</div>\n      <p><strong>Cas particulier</strong> — en cas d'<span class=\"kw-clinique\">eczéma variqueux</span> : <span class=\"kw-ttt\">dermocorticoïdes</span> + <span class=\"kw-ttt\">émollients</span>, en plus des mesures précédentes.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 225 — Artériopathie oblitérante - anévrysme · 222 — FDR cardiovasculaire</em></p>","frequence":4}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"liensGlobaux":[{"href":"https://radiopaedia.org/articles/chronic-venous-insufficiency","label":"Radiopaedia : Chronic venous insufficiency"},{"href":"https://radiopaedia.org/articles/may-thurner-syndrome-2","label":"Radiopaedia : May thurner syndrome 2"},{"href":"https://fr.wikipedia.org/wiki/Syndrome_de_May-Thurner","label":"Wikipedia — Syndrome de may thurner"}],"cards":[{"i":"105a44e1a771","n":227,"o":"227-1","u":"Définition","t":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","q":"Quelle est la définition de l'insuffisance veineuse chronique (IVC) ?","a":"<p>L'insuffisance veineuse chronique (IVC) est une <strong>dysfonction du système veineux profond et/ou superficiel</strong>, préférentiellement des membres inférieurs. Elle est causée par une <strong>incontinence valvulaire</strong>, associée ou non à une oblitération veineuse.</p>"},{"i":"23a05fa3f654","n":227,"o":"227-1","u":"Définition","t":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","q":"Quel piège doit-on connaître concernant le diagnostic des varices ?","a":"<p>Il est important de distinguer les varices pathologiques des <strong>« varices du sportif »</strong>, qui sont dues à une simple lyse du tissu adipeux et n'ont pas de signification pathologique.</p>"},{"i":"8e92e6b88958","n":227,"o":"227-1","u":"Définition","t":"Connaître la définition d’une insuffisance veineuse chronique (IVC) et des varices","q":"Qu'est-ce qu'une varice, et quelles sont ses caractéristiques observées à l'inspection ?","a":"<p>Une varice est une <strong>dilatation permanente et pathologique</strong> d'une ou plusieurs veines superficielles des membres inférieurs.</p><p>À l'inspection, elles apparaissent comme des veines <strong>dilatées et tortueuses</strong>, sous-cutanées et visibles, avec un diamètre <strong>supérieur à 3 mm en orthostatisme</strong>, et sont associées à un reflux entraînant une stase du sang veineux.</p>"},{"i":"257e6a3a8cbf","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quels sont les signes cliniques recherchés pour le diagnostic positif du syndrome post-thrombotique ?","a":"<p>Le diagnostic positif associe des <strong>signes cliniques d'insuffisance veineuse chronique</strong> (IVC) et des <strong>signes d'antécédent de phlébite</strong>. Le score de Villalta est utilisé pour en coter la sévérité, évaluant des symptômes subjectifs (lourdeur, douleur, crampes, prurit, paresthésies) et des signes objectifs (œdème, douleur à la pression des mollets, induration de la peau, hyperpigmentation, rougeur).</p>"},{"i":"754ae296b447","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quels sont les deux mécanismes physiopathologiques principaux du syndrome post-thrombotique ?","a":"<ul><li>Une <strong>obstruction résiduelle chronique d'une veine profonde</strong> entraînant une élévation des pressions en amont et une redistribution du retour veineux vers le réseau superficiel.</li><li>Un <strong>syndrome de recanalisation du thrombus</strong> avec destruction des valvules et apparition d'un reflux valvulaire profond.</li></ul>"},{"i":"85b1ece8c47c","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quelle intervention est contre-indiquée en cas de syndrome post-thrombotique avec varices secondaires, et pourquoi ?","a":"<p>L'<strong>éveinage</strong> est contre-indiqué en cas d'insuffisance veineuse sur syndrome post-thrombotique. En effet, les <strong>varices secondaires</strong> suppléent alors l'obstruction veineuse profonde et leur retrait aggraverait la situation.</p>"},{"i":"b3756240a355","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quel rôle l'écho-Doppler veineux joue-t-il dans le diagnostic du syndrome post-thrombotique ?","a":"<p>L'écho-Doppler veineux permet de mettre en évidence les <strong>séquelles de thrombose veineuse profonde</strong>, notamment un <strong>syndrome obstructif</strong> et/ou des <strong>reflux profonds</strong>.</p>"},{"i":"bd1a26c4ae50","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quelle est la définition du syndrome post-thrombotique (SPT) ?","a":"<p>Le syndrome post-thrombotique est une <strong>séquelle de thrombose veineuse profonde</strong> (TVP) se développant généralement quelques années après l'épisode aigu.</p>"},{"i":"d1e52f99f2fd","n":227,"o":"227-3","u":"Définition","t":"Connaître la définition d’un syndrome post-thrombotique","q":"Quelle est la prise en charge préventive du syndrome post-thrombotique ?","a":"<p>La prévention du syndrome post-thrombotique repose dès le diagnostic de la phlébite sur une <strong>anticoagulation efficace</strong> et l'instauration d'une <strong>compression élastique</strong>. La compression maintenue pendant au moins 3 mois réduit le risque de SPT de 50%.</p>"},{"i":"18325c2cc236","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Quels sont les facteurs favorisants comportementaux ou liés au mode de vie pour l'insuffisance veineuse chronique (IVC) et les varices ?","a":"<ul><li>La <strong>sédentarité</strong>.</li><li>L'<strong>obésité</strong> et le <strong>surpoids</strong>.</li><li>La <strong>constipation chronique</strong>.</li><li>L'<strong>exposition à la chaleur</strong>.</li></ul>"},{"i":"226c83ea3d17","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Parmi l'orthostatisme prolongé et la marche prolongée, lequel est un facteur favorisant de l'insuffisance veineuse chronique (IVC) et des varices ?","a":"<p>L'<strong>orthostatisme prolongé</strong> (station debout immobile) est un facteur favorisant de l'insuffisance veineuse chronique (IVC) et des varices. La <strong>marche prolongée n'est PAS un facteur de risque</strong> car la marche active favorise la pompe musculaire du mollet.</p>"},{"i":"5016f311aa33","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Quels sont les facteurs favorisants liés aux spécificités démographiques ou physiologiques de l'insuffisance veineuse chronique (IVC) et des varices ?","a":"<ul><li>L'<strong>âge</strong>.</li><li>Le <strong>sexe féminin</strong>.</li><li>Les <strong>grossesses multiples</strong>.</li></ul>"},{"i":"9f8d7c4bfd22","n":227,"o":"227-5","u":"Étiologies","t":"Connaître les facteurs favorisant l’IVC","q":"Quel est le facteur favorisant le plus important pour l'insuffisance veineuse chronique (IVC) et les varices ?","a":"<p>Le facteur favorisant majeur de l'insuffisance veineuse chronique (IVC) et des varices est l'<strong>hérédité</strong>.</p>"},{"i":"409c29750a45","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Comment les symptômes de l'insuffisance veineuse chronique (IVC) évoluent-ils en fonction de certains facteurs ?","a":"<p>Les symptômes de l'IVC sont :</p><ul><li>Aggravés par la <strong>station debout ou assise prolongée</strong>, la <strong>chaleur</strong>, la <strong>grossesse</strong>, les <strong>œstroprogestatifs</strong>, la <strong>période prémenstruelle</strong>.</li><li>Améliorés par le <strong>froid</strong>, la <strong>surélévation des membres inférieurs</strong>, le <strong>décubitus</strong>, l'<strong>exercice physique</strong>, la <strong>compression veineuse élastique</strong>.</li></ul>"},{"i":"a2409dec991d","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Quels sont les signes cutanés de l'insuffisance veineuse chronique (IVC), du plus précoce au plus avancé ?","a":"<p>Les signes cutanés de l'IVC, du plus précoce au plus avancé, sont :</p><ul><li><strong>Télangiectasies</strong> (dilatations intradermiques &lt; 1 mm)</li><li><strong>Veines réticulaires</strong> (dilatations sous-dermiques ramifiées de 1 à 3 mm), pouvant former une <strong>corona phlebectatica</strong> à la cheville/arche plantaire, signe précurseur d'ulcère.</li><li><strong>Varices</strong> (veines superficielles dilatées, tortueuses et saillantes &gt; 3 mm).</li><li><strong>Œdème</strong> (blanc, mou, prend le godet, recrudescence vespérale).</li><li><strong>Troubles trophiques</strong> : <ul><li><strong>Eczéma variqueux</strong></li><li><strong>Dermite ocre</strong></li><li><strong>Atrophie blanche de Millian</strong></li><li><strong>Hypodermite / lipodermatosclérose</strong></li></ul></li><li><strong>Ulcère veineux</strong> (stade ultime de l'IVC).</li></ul>"},{"i":"a5327fd36d92","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Quels sont les symptômes fréquents et peu spécifiques de l'insuffisance veineuse chronique (IVC) qui varient avec la stase veineuse ?","a":"<p>Les symptômes fréquents de l'IVC sont :</p><ul><li><strong>Lourdeurs et pesanteurs des membres inférieurs</strong></li><li><strong>Crampes</strong></li><li><strong>Fatigabilité du mollet</strong></li><li><strong>Phlébalgie</strong> (trajet veineux douloureux sans induration)</li><li><strong>Prurit et gêne esthétique</strong></li><li><strong>Impatiences nocturnes</strong></li><li><strong>Brûlures, rougeur du pied</strong> après quelques heures de sommeil ou en déclivité, soulagées par le froid</li><li><strong>Claudication intermittente veineuse</strong> (n'empêche pas la poursuite de la marche, ne cède pas à l'arrêt mais cède en décubitus)</li></ul>"},{"i":"ba5834c8c391","n":227,"o":"227-7","u":"Diagnostic positif","t":"Identifier les varices et l’IVC","q":"Quel est l'examen clinique à réaliser pour un patient suspecté d'insuffisance veineuse chronique (IVC) et de varices ?","a":"<p>L'examen clinique doit être réalisé en <strong>position debout sur un escabeau de phlébologie</strong>, il est <strong>bilatéral et comparatif</strong> et comprend :</p><ul><li>L'<strong>inspection</strong> : recherche de varices, varicosités, complications cutanées.</li><li>La <strong>palpation</strong> : recherche de phlébalgie, d'induration (évoquant une thrombose).</li><li>L'<strong>auscultation</strong> : recherche d'un souffle (évoquant une fistule artério-veineuse).</li></ul><p>Les manœuvres cliniques (signe du flot, signe de Schwartz, épreuve de Trendelenburg) sont hors programme de l'EDN.</p>"},{"i":"5779b3deb22a","n":227,"o":"227-8","u":"Diagnostic positif","t":"Savoir reconnaître un ulcère variqueux","q":"Quels sont les principaux critères cliniques permettant de distinguer un ulcère variqueux d'un ulcère artériel ?","a":"<ul><li><strong>Terrain :</strong> L'ulcère variqueux touche préférentiellement la <strong>femme de plus de 50 ans</strong>, avec des antécédents de <strong>TVP</strong>, de <strong>varices</strong> ou de <strong>surpoids</strong>.</li><li><strong>Localisation :</strong> Il est typiquement <strong>péri-malléolaire</strong>, jusqu'au 1/3 inférieur du mollet, avec des <strong>bords réguliers</strong>.</li><li><strong>Douleur :</strong> Il est généralement <strong>peu ou pas douloureux</strong>.</li><li><strong>Profondeur :</strong> Il est <strong>superficiel</strong> et non creusant.</li><li><strong>Fond :</strong> Le fond est souvent <strong>exsudatif et fibrineux</strong>.</li><li><strong>Peau péri-ulcéreuse :</strong> Elle présente souvent des <strong>varices</strong>, des <strong>télangiectasies</strong>, un <strong>eczéma variqueux</strong>, une <strong>dermite ocre</strong>, une <strong>atrophie blanche</strong> ou une <strong>corona phlébectatique</strong>, et l'examen artériel est normal.</li></ul>"},{"i":"d789864e18f3","n":227,"o":"227-8","u":"Diagnostic positif","t":"Savoir reconnaître un ulcère variqueux","q":"Quel est l'intérêt et la valeur de l'Index de Pression Systolique (IPS) pour le diagnostic étiologique des ulcères de jambe, notamment l'ulcère variqueux ?","a":"<p>L'<strong>IPS</strong> est une mesure <strong>systématique</strong> devant tout ulcère de jambe. Pour un ulcère variqueux pur, l'IPS est <strong>normal, entre 0,9 et 1,3</strong>. Un IPS <strong>inférieur à 0,9</strong> oriente vers un ulcère artériel, tandis qu'une valeur <strong>entre 0,7 et 0,9</strong> suggère un ulcère mixte à prédominance veineuse. Il est fondamental car il <strong>conditionne la possibilité d'une compression élastique</strong>, qui est contre-indiquée en cas d'artériopathie sévère (IPS bas).</p>"},{"i":"d7c648a24f64","n":227,"o":"227-8","u":"Diagnostic positif","t":"Savoir reconnaître un ulcère variqueux","q":"Comment définir et caractériser l'ulcère variqueux par rapport aux autres ulcères de jambe ?","a":"<p>L'ulcère variqueux, également appelé ulcère veineux, est le <strong>plus fréquent</strong> des ulcères de jambe, représentant environ <strong>80 %</strong> des cas.</p>"},{"i":"2e9129fcab8f","n":227,"o":"227-9","u":"Diagnostic positif","t":"Connaître les méthodes diagnostiques de l’IVC","q":"Les manœuvres cliniques spécifiques (signe du flot, signe de Schwartz, épreuve de Trendelenburg) sont-elles à connaître pour le diagnostic d'insuffisance veineuse chronique dans le cadre de l'EDN français ?","a":"<p>Non, les manœuvres cliniques spécifiques telles que le signe du flot, le signe de Schwartz et l'épreuve de Trendelenburg sont <strong>hors programme</strong> pour l'EDN français.</p>"},{"i":"b2d866122902","n":227,"o":"227-9","u":"Diagnostic positif","t":"Connaître les méthodes diagnostiques de l’IVC","q":"Quelles sont les indications de l'échographie-Doppler veineuse des membres inférieurs dans le contexte de l'insuffisance veineuse chronique (IVC) ?","a":"<ul><li>Confirmer le diagnostic d'IVC.</li><li>Bilan pré-opératoire (systématique avant chirurgie variqueuse).</li><li>Bilan pré-sclérose : cartographie veineuse et mesure du diamètre des varices.</li><li>Bilan d'un ulcère des membres inférieurs.</li><li>Suspicion de thrombose veineuse profonde (TVP).</li></ul>"},{"i":"ffb0fcb5007f","n":227,"o":"227-9","u":"Diagnostic positif","t":"Connaître les méthodes diagnostiques de l’IVC","q":"Quel est l'examen de référence pour le diagnostic de l'insuffisance veineuse chronique (IVC) et dans quelle position doit-il être réalisé ?","a":"<p>L'examen de référence pour le diagnostic de l'insuffisance veineuse chronique (IVC) est l'<strong>échographie-Doppler veineuse des membres inférieurs</strong>. Il doit être réalisé en <strong>position debout</strong>.</p>"}]};